from jinja2 import Template
from xhtml2pdf import pisa
import os

def generate_pdf_with_jinja(agent_json, market_data, llm_narrative):
    zip_code = agent_json["zip_codes"][0]
    filename = f"SnapReport_{zip_code}.pdf"

    # Notice how @bottom-center is completely removed and replaced with @frame
    html_template = """
    <!DOCTYPE html>
    <html>
    <head>
        <meta charset="utf-8">
        <style>
            @page {
                size: letter;
                margin: 0.6in 0.7in 0.8in 0.7in;
                @frame footer_frame {
                    -pdf-frame-content: footer_content;
                    bottom: 0.3in;
                    margin-left: 0.7in;
                    margin-right: 0.7in;
                    height: 0.3in;
                }
            }
            body {
                font-family: Helvetica, Arial, sans-serif;
                color: #334155;
                line-height: 1.6;
                margin: 0;
                padding: 0;
            }
            #footer_content {
                text-align: center;
                font-size: 8pt;
                color: #94A3B8;
            }
            .header-table {
                width: 100%;
                border-collapse: collapse;
                margin-bottom: 20px;
            }
            .logo { max-height: 42px; display: block; }
            .brokerage-text {
                font-size: 24px; font-weight: bold; color: #1E3A8A; margin: 0;
            }
            .agent-info-table { float: right; border-collapse: collapse; }
            .agent-details-cell { text-align: right; padding-right: 14px; vertical-align: middle; }
            .agent-name { font-size: 16px; font-weight: bold; color: #1E3A8A; margin: 0 0 3px 0; }
            .agent-detail { font-size: 11px; color: #64748B; margin: 0; line-height: 1.4; }
            .agent-photo-cell { vertical-align: middle; width: 64px; }
            .profile-pic {
                width: 60px; height: 60px; border: 2px solid #E2E8F0; display: block;
            }
            .divider { width: 100%; height: 1px; background-color: #E2E8F0; margin: 5px 0 25px 0; clear: both; }
            .report-title { font-size: 26px; font-weight: bold; color: #1E3A8A; margin: 0 0 4px 0; }
            .report-subtitle { font-size: 13px; color: #64748B; font-weight: normal; margin: 0 0 24px 0; }
            .narrative-box { background-color: #F8FAFC; border-left: 4px solid #3B82F6; padding: 18px 20px; margin-bottom: 32px; }
            .narrative-label { font-size: 13px; font-weight: bold; color: #2563EB; margin: 0 0 6px 0; text-transform: uppercase; }
            .narrative-text { font-size: 12px; color: #334155; line-height: 1.65; margin: 0; }
            .section-title { font-size: 15px; font-weight: bold; color: #1E3A8A; margin: 0 0 12px 0; text-transform: uppercase; }
            .metrics-table { width: 100%; border-collapse: collapse; margin-bottom: 20px; border: 1px solid #E2E8F0; }
            .metrics-table th { background-color: #1E3A8A; color: #FFFFFF; font-size: 11px; font-weight: bold; padding: 12px 16px; text-align: left; text-transform: uppercase; }
            .metrics-table td { font-size: 13px; padding: 12px 16px; border-bottom: 1px solid #E2E8F0; color: #334155; }
            .metric-value { font-weight: bold; color: #1E3A8A; text-align: right; }
            .row-even { background-color: #F8FAFC; }
            .row-odd  { background-color: #FFFFFF; }
        </style>
    </head>
    <body>
        <div id="footer_content">
            Powered by {{ agent.brokerage }} &bull; Confidential Market Update
        </div>

        <table class="header-table">
            <tr>
                <td style="vertical-align: middle; width: 45%;">
                    {% if agent.logo_url %}
                    <img src="{{ agent.logo_url }}" class="logo">
                    {% else %}
                    <p class="brokerage-text">{{ agent.brokerage }}</p>
                    {% endif %}
                </td>
                <td style="vertical-align: middle; width: 55%;">
                    <table class="agent-info-table">
                        <tr>
                            <td class="agent-details-cell">
                                <p class="agent-name">{{ agent.name }}</p>
                                <p class="agent-detail">{{ agent.phone }}</p>
                                <p class="agent-detail">{{ agent.email }}</p>
                            </td>
                            {% if agent.photo_url %}
                            <td class="agent-photo-cell">
                                <img src="{{ agent.photo_url }}" class="profile-pic">
                            </td>
                            {% endif %}
                        </tr>
                    </table>
                </td>
            </tr>
        </table>

        <div class="divider"></div>

        <p class="report-title">SnapReport&trade; Market Intelligence</p>
        <p class="report-subtitle">Hyperlocal Update for Zip Code {{ agent.zip_codes[0] }} &mdash; {{ market.city }}</p>

        <div class="narrative-box">
            <p class="narrative-label">Local Market Analysis</p>
            <p class="narrative-text">{{ narrative }}</p>
        </div>

        <p class="section-title">Core Market Metrics</p>

        <table class="metrics-table">
            <thead>
                <tr>
                    <th style="width: 60%;">Metric</th>
                    <th style="width: 40%; text-align: right;">Current Value</th>
                </tr>
            </thead>
            <tbody>
                <tr class="row-odd">
                    <td>Median Home Price</td>
                    <td class="metric-value">${{ "{:,}".format(market.median_price) }}</td>
                </tr>
                <tr class="row-even">
                    <td>Average Days on Market</td>
                    <td class="metric-value">{{ market.days_on_market }} Days</td>
                </tr>
                <tr class="row-odd">
                    <td>List-to-Sale Price Ratio</td>
                    <td class="metric-value">{{ market.list_to_sale_ratio }}%</td>
                </tr>
            </tbody>
        </table>
    </body>
    </html>
    """

    template = Template(html_template)
    rendered_html = template.render(
        agent=agent_json,
        market=market_data,
        narrative=llm_narrative
    )

    print(f"Generating PDF structure for {zip_code}...")
    with open(filename, "w+b") as result_file:
        pisa_status = pisa.CreatePDF(rendered_html, dest=result_file)
        
    if pisa_status.err:
        print(f"Error generating PDF: {pisa_status.err}")
    else:
        print(f"Success! Saved as: {filename}")

